/* Warehouse Phase 1 outbound order. Previous version: V2.0.28 */
SET NAMES utf8mb4;
CREATE TABLE `wm_outbound_order` (`id` BIGINT NOT NULL,`outbound_no` VARCHAR(64) NOT NULL,`company_id` BIGINT NOT NULL,`project_id` BIGINT DEFAULT NULL,`warehouse_id` BIGINT NOT NULL,`outbound_type` VARCHAR(32) NOT NULL,`status` VARCHAR(16) NOT NULL DEFAULT 'DRAFT',`outbound_at` DATETIME NOT NULL,`confirmed_at` DATETIME DEFAULT NULL,`completed_at` DATETIME DEFAULT NULL,`cancelled_at` DATETIME DEFAULT NULL,`operator_id` BIGINT DEFAULT NULL,`source_type` VARCHAR(32) DEFAULT NULL,`source_id` BIGINT DEFAULT NULL,`source_no` VARCHAR(64) DEFAULT NULL,`create_dept` BIGINT DEFAULT NULL,`create_by` BIGINT DEFAULT NULL,`create_time` DATETIME DEFAULT NULL,`update_by` BIGINT DEFAULT NULL,`update_time` DATETIME DEFAULT NULL,`remark` VARCHAR(500) DEFAULT NULL,`del_flag` CHAR(1) NOT NULL DEFAULT '0',PRIMARY KEY(`id`),UNIQUE KEY `uk_wm_outbound_no`(`outbound_no`),KEY `idx_wm_outbound_warehouse_status`(`warehouse_id`,`status`,`outbound_at`),KEY `idx_wm_outbound_source`(`source_type`,`source_id`),CONSTRAINT `chk_wm_outbound_status` CHECK(`status` IN('DRAFT','CONFIRMED','COMPLETED','CANCELLED'))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='出库单';
CREATE TABLE `wm_outbound_order_item` (`id` BIGINT NOT NULL,`outbound_order_id` BIGINT NOT NULL,`material_id` BIGINT NOT NULL,`location_id` BIGINT NOT NULL,`unit_id` BIGINT NOT NULL,`quantity` DECIMAL(19,6) NOT NULL,`create_dept` BIGINT DEFAULT NULL,`create_by` BIGINT DEFAULT NULL,`create_time` DATETIME DEFAULT NULL,`update_by` BIGINT DEFAULT NULL,`update_time` DATETIME DEFAULT NULL,`remark` VARCHAR(500) DEFAULT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uk_wm_outbound_item`(`outbound_order_id`,`material_id`,`location_id`),KEY `idx_wm_outbound_item_order`(`outbound_order_id`),KEY `idx_wm_outbound_item_material`(`material_id`),KEY `idx_wm_outbound_item_location`(`location_id`),CONSTRAINT `chk_wm_outbound_item_qty` CHECK(`quantity`>0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='出库单明细';
